pair D, P, R, V;

D = (2,1);
V = (-2,3);
R = reflect((0,0),D)*(V);
P = (V + R)/2;

draw((-2,0)--(3,0));
draw((0,-4)--(0,3));
draw((-D)--D,Arrow(6));
draw((0,0)--V,red,Arrow(6));
